// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint256 timeOffset) public {
        vm.assume(amount == 10 ether);
        vm.assume(timeOffset > 0 && timeOffset < 1000000);

        uint256 currentTime = block.timestamp;
        vm.warp(currentTime + timeOffset);

        // Ensure previous block condition might trigger (block.number % 15 could be 0)
        // We just call the fallback and check the state
        (bool success, ) = address(c).call{value: amount}("");
        if (success) {
            assertTrue(c.pastBlockTime() == block.timestamp);
        }
    }
}

